```suggestion
// In-memory provider registry and simple event/listener implementation.
const _providers: EditorProvider[] = [];
const _onDidRegisterListeners: Array<(e: EditorProviderRegisteredEvent) => void> = [];
const _onDidUnregisterListeners: Array<(e: EditorProviderUnregisteredEvent) => void> = [];

export function registerEditorProvider(
  contribution: EditorContribution,
  component: EditorComponent,
): Disposable {
  const provider: EditorProvider = { contribution, component };
  _providers.push(provider);
  // Notify listeners
  _onDidRegisterListeners.slice().forEach(l => l({ provider }));

  // Return a disposable which removes this provider and notifies unregistered listeners
  return {
    dispose() {
      const idx = _providers.indexOf(provider);
      if (idx >= 0) {
        _providers.splice(idx, 1);
        _onDidUnregisterListeners.slice().forEach(l => l({ contribution }));
      }
    },
  } as Disposable;
}

/**
 * Get the editor provider for a specific language.
 * Returns the extension's editor if registered, otherwise undefined.
 */
export function getEditorProvider(language: EditorLanguage): EditorProvider | undefined {
  // Find last-registered provider that supports the language (last wins)
  for (let i = _providers.length - 1; i >= 0; i -= 1) {
    const p = _providers[i];
    // contributions typically declare `languages`; guard with any to avoid strict type assumptions
    const langs = (p.contribution as any).languages as EditorLanguage[] | undefined;
    if (langs && langs.includes(language)) {
      return p;
    }
  }
  return undefined;
}

export function hasEditorProvider(language: EditorLanguage): boolean {
  return !!getEditorProvider(language);
}

export function getAllEditorProviders(): EditorProvider[] {
  return _providers.slice();
}

// Simple Event<T> implementation compatible with common patterns (subscribe returns Disposable)
export const onDidRegisterEditorProvider: Event<EditorProviderRegisteredEvent> = (listener) => {
  _onDidRegisterListeners.push(listener);
  return {
    dispose() {
      const idx = _onDidRegisterListeners.indexOf(listener);
      if (idx >= 0) _onDidRegisterListeners.splice(idx, 1);
    },
  } as Disposable;
};

export const onDidUnregisterEditorProvider: Event<EditorProviderUnregisteredEvent> = (listener) => {
  _onDidUnregisterListeners.push(listener);
  return {
    dispose() {
      const idx = _onDidUnregisterListeners.indexOf(listener);
      if (idx >= 0) _onDidUnregisterListeners.splice(idx, 1);
    },
  } as Disposable;
};
```
<details>
<summary><b>Steps of Reproduction ✅ </b></summary>

```mdx
1. Open the runtime API declarations at
`superset-frontend/packages/superset-core/src/api/editors.ts:342-381`. These lines only
use `export declare` signatures and do not emit runtime implementations.

2. Start the Superset frontend dev server (the app compiles and serves frontend bundles).
At runtime the compiled JS for this module will not contain functions because `export
declare` produces no implementation.

3. Install or enable an extension that calls `registerEditorProvider(...)` during
activation (the example Editors Bundle referenced in PR description registers providers).
When that extension's initialization calls `registerEditorProvider(...)` at runtime, the
imported symbol resolves to undefined (no JS function), producing a TypeError like
"registerEditorProvider is not a function".

4. The EditorHost / host code that tries to call `getEditorProvider(language)` will
likewise find no runtime implementation and fail to resolve providers. Because the
declarations are present but no implementation exists, extension registration and provider
lookup will not function at runtime.
